import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random, Easing } from '../remotionShim';
// { /* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// { /* End Google Fonts Loader */ }



export type CrtTurnOffProps = Record<string, any>;

const CrtTurnOff: React.FC<CrtTurnOffProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 5,
  screenColor = "#e6e6e6",
  turnOffStartFrame = 90,
  scanlineIntensity = 0.15,
  grainIntensity = 0.2,
  flickerAmount = 0.03,
}) => {
  useFontLoader([]); // No fonts needed, but hook retained for structure stability

  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // --- Animation Timings ---
  // 1. Vertical Crush: Compresses to a horizontal line
  const crushDuration = 8;
  // 2. Horizontal Shrink: Line shrinks inward and fades out
  const shrinkDuration = 12;

  // --- Phase 1: Vertical Crush (Scale Y) ---
  const scaleY = interpolate(
    frame,
    [turnOffStartFrame, turnOffStartFrame + crushDuration],
    [1, 0.004], // Compresses to ~0.4% height (thin line)
    {
      easing: Easing.bezier(0.8, 0, 1, 1), // Fast start, sharp stop
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // --- Phase 2: Horizontal Shrink (Scale X) ---
  // Starts after vertical crush is mostly done
  const scaleX = interpolate(
    frame,
    [turnOffStartFrame + crushDuration, turnOffStartFrame + crushDuration + shrinkDuration],
    [1, 0.0],
    {
      easing: Easing.out(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // --- Phase 3: Opacity Fade (The Band Fading) ---
  const screenOpacity = interpolate(
    frame,
    [turnOffStartFrame + crushDuration, turnOffStartFrame + crushDuration + shrinkDuration],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // --- Hard Cut ---
  // Ensure absolute blackness after animation finishes
  const isCut = frame >= turnOffStartFrame + crushDuration + shrinkDuration;

  // --- Visual Effects Logic ---
  // Flicker: Random variation based on current frame
  const currentFlicker = random(frame) * flickerAmount;
  
  // Grain: Animated seed for SVG turbulence
  const grainSeed = Math.floor(frame / 2); // Update every 2 frames for "film" look

  // Background handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Scanline gradient (CSS)
  const scanlineBackground = `repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 2px,
    rgba(0, 0, 0, ${scanlineIntensity}) 3px,
    rgba(0, 0, 0, ${scanlineIntensity}) 4px
  )`;

  if (isCut) {
    return (
      <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
        {/* Render nothing (black/transparent) after cut */}
      </AbsoluteFill>
    );
  }

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor, overflow: "hidden" }}>
      {/* SVG Filters Definition */}
      <svg style={{ position: "absolute", width: 0, height: 0 }}>
        <defs>
          <filter id="crt-grain">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.8"
              numOctaves="2"
              stitchTiles="stitch"
              seed={grainSeed}
            />
            <feColorMatrix type="saturate" values="0" />
            <feComponentTransfer>
              <feFuncA type="linear" slope={grainIntensity} />
            </feComponentTransfer>
          </filter>
        </defs>
      </svg>

      {/* The CRT Screen */}
      <AbsoluteFill
        style={{
          backgroundColor: screenColor,
          transform: `scale(${scaleX}, ${scaleY})`,
          opacity: screenOpacity - currentFlicker,
          // Use flex to center if scale changes origin
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transformOrigin: "center center",
        }}
      >
        {/* Grain Layer */}
        <AbsoluteFill
          style={{
            filter: "url(#crt-grain)",
            opacity: 1,
            mixBlendMode: "multiply",
          }}
        />

        {/* Scanlines Layer */}
        <AbsoluteFill
          style={{
            background: scanlineBackground,
            mixBlendMode: "overlay",
            pointerEvents: "none",
          }}
        />

        {/* Subtle Vignette (Optional for depth, keeps edges soft) */}
        <AbsoluteFill
          style={{
            background: "radial-gradient(circle, transparent 60%, rgba(0,0,0,0.2) 100%)",
            pointerEvents: "none",
          }}
        />
        
        {/* Content Placeholder / Image simulation */}
        <div style={{
            width: "100%",
            height: "100%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            color: "rgba(0,0,0,0.1)",
            fontSize: width * 0.1,
            fontWeight: "bold",
            fontFamily: "monospace"
        }}>
            {/* Empty by default, simulates the "image" */}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CrtTurnOff;